package handler
import("encoding/json";"net/http";"strconv";"github.com/go-chi/chi/v5";"go-repair-center/internal/repository";"go-repair-center/internal/service";"go-repair-center/internal/transport/http/dto";"go-repair-center/internal/transport/http/middleware";"go-repair-center/internal/transport/http/response")
type UserHandler struct{*GenericHandler;users *service.UserService}
func NewUserHandler(users *service.UserService)*UserHandler{return &UserHandler{GenericHandler:NewGenericHandler(users,"user"),users:users}}
func(h *UserHandler)Routes(router chi.Router){router.Route("/users",func(resource chi.Router){resource.With(middleware.Require("system:user:manage")).Get("/",h.List);resource.With(middleware.Require("system:user:manage")).Post("/",h.CreateUser);resource.With(middleware.Require("system:user:manage")).Get("/{id}",h.Get);resource.With(middleware.Require("system:user:manage")).Put("/{id}",h.Update);resource.With(middleware.Require("system:user:manage")).Put("/{id}/enable",h.Enable);resource.With(middleware.Require("system:user:manage")).Put("/{id}/disable",h.Disable);resource.With(middleware.Require("system:user:manage")).Post("/{id}/reset-password",h.ResetPassword)})}
func(h *UserHandler)CreateUser(w http.ResponseWriter,r *http.Request){input:=repository.Record{};if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};user,err:=h.users.CreateUser(r.Context(),input);if err!=nil{writeError(w,r,err);return};delete(user,"password_hash");response.Created(w,user,middleware.RequestID(r.Context()))}
func(h *UserHandler)ResetPassword(w http.ResponseWriter,r *http.Request){id,_:=strconv.ParseInt(chi.URLParam(r,"id"),10,64);var input dto.ResetPasswordRequest;if err:=json.NewDecoder(r.Body).Decode(&input);err!=nil{writeError(w,r,err);return};if err:=h.users.ResetPassword(r.Context(),id,input.NewPassword);err!=nil{writeError(w,r,err);return};response.Success(w,map[string]bool{"reset":true},middleware.RequestID(r.Context()))}
func(h *UserHandler)Enable(w http.ResponseWriter,r *http.Request){id,_:=strconv.ParseInt(chi.URLParam(r,"id"),10,64);user,err:=h.users.SetEnabled(r.Context(),id,true);if err!=nil{writeError(w,r,err);return};response.Success(w,user,middleware.RequestID(r.Context()))}
func(h *UserHandler)Disable(w http.ResponseWriter,r *http.Request){id,_:=strconv.ParseInt(chi.URLParam(r,"id"),10,64);user,err:=h.users.SetEnabled(r.Context(),id,false);if err!=nil{writeError(w,r,err);return};response.Success(w,user,middleware.RequestID(r.Context()))}
